"""Business log center page backed by the app_logs table."""


def logs_html() -> str:
    return r'''<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>日志中心 · 115娱乐中心</title><style>
:root{--line:#174c54;--gold:#d3b370;--cyan:#16b9d1;--text:#e7ddc7;--muted:#978b73}*{box-sizing:border-box}body{margin:0;background:radial-gradient(circle at 72% 3%,#2a2013 0,#090805 40%,#050504 100%);color:var(--text);font:14px system-ui,-apple-system,"Microsoft YaHei",sans-serif}.shell{display:grid;grid-template-columns:235px minmax(0,1fr);min-height:100vh}.side{background:#090805ef;border-right:1px solid var(--line);padding:18px 10px}.logo{font-size:21px;font-weight:800;color:var(--gold);padding:7px 12px 28px}.group{font-size:11px;color:#776c58;margin:14px 10px 7px;border-bottom:1px solid #3e341f;padding-bottom:8px}.nav{display:block;color:#c0ae89;text-decoration:none;padding:13px 16px;margin:3px 0;border-radius:12px;font-weight:700}.nav:hover,.nav.active{background:#113a40;color:#39d4e9}.main{min-width:0}.top{height:64px;display:flex;align-items:center;padding:0 28px;background:#080705ed;border-bottom:1px solid var(--line)}.heading{font-size:22px;font-weight:800;color:#35c7dd}.refresh{margin-left:auto;border:1px solid #275a5e;background:#17150f;color:#d7bf8b;border-radius:10px;padding:9px 18px}.wrap{max-width:1540px;margin:auto;padding:22px 26px}.filters{display:grid;grid-template-columns:minmax(200px,1fr) 150px 170px 170px auto;gap:10px;padding:14px;background:#15120d;border:1px solid var(--line);border-radius:14px;margin-bottom:12px}.control{height:43px;background:#090907;border:1px solid #205966;border-radius:9px;color:#ddd;padding:0 12px}.btn{border:1px solid #5f4827;background:#241a0e;color:#d8bb7d;border-radius:9px;padding:0 14px}.panel{background:#0f0e0a;border:1px solid var(--line);border-radius:15px;overflow:hidden;min-height:500px}.thead,.row{display:grid;grid-template-columns:130px 72px 90px minmax(0,1fr);align-items:center;gap:10px;padding:11px 16px}.thead{background:#1a160e;color:#90826a;border-bottom:1px solid var(--line);position:sticky;top:0}.row{border-bottom:1px solid #123f46}.row:hover{background:#15120c}.time{color:#b8aa8e;font-size:12px}.lv{font-weight:800;font-size:12px}.lv.INFO{color:#62db91}.lv.WARNING{color:#e2c06f}.lv.ERROR,.lv.CRITICAL{color:#ff8790}.mod{color:#4ad8e9;font-size:12px}.msg{color:#cfc3ab;word-break:break-all;line-height:1.5}.state{text-align:center;padding:90px 20px;color:#9d917d}.state h2{color:#d8bc7c}.pager{display:flex;justify-content:center;align-items:center;gap:12px;padding:16px}.pager button{border:1px solid #235b63;background:#17140e;color:#d8bd7f;border-radius:50%;width:38px;height:38px}.pager button:disabled{opacity:.3}.toast{position:fixed;right:24px;bottom:24px;padding:13px 17px;border-radius:10px;background:#153b31;border:1px solid #45b981;color:#bff5d5;display:none}.toast.bad{background:#3b1e20;border-color:#b44b54;color:#ffd0d3}@media(max-width:900px){.shell{display:block}.side{display:none}.wrap{padding:12px}.filters{grid-template-columns:1fr 1fr}.filters input{grid-column:1/-1}.thead{display:none}.row{grid-template-columns:90px 60px 1fr;border:1px solid var(--line);border-radius:12px;margin:8px 0;background:#12100b}.msg{grid-column:1/-1}}
</style></head><body><div class="shell"><aside class="side"><div class="logo">◉ 影舟 MovieArk</div><div class="group">发现</div><a class="nav" href="/rankings">🏆 榜单</a><a class="nav" href="/explore">◉ 汇影</a><a class="nav" href="/search">⌕ 搜索</a><div class="group">订阅</div><a class="nav" href="/subscriptions">☷ 订阅列表</a><a class="nav" href="/tasks">▣ 订阅任务</a><a class="nav" href="/unlocks">◴ 解锁记录</a><div class="group">系统</div><a class="nav" href="/authorizations">🔑 授权中心</a><a class="nav" href="/settings">⚙ 业务设置</a><a class="nav" href="/telegram">✈ Telegram</a><a class="nav active" href="/logs">▤ 日志中心</a></aside><main class="main"><header class="top"><div class="heading">▤ 日志中心</div><label class="control" style="margin-left:18px;display:flex;align-items:center;gap:6px;height:36px"><input id="auto" type="checkbox" style="width:auto"> 自动刷新</label><button class="refresh" id="refresh">刷新</button></header><section class="wrap"><div class="filters"><input class="control" id="keyword" placeholder="关键词（影片名 / 资源ID / 错误信息）"><select class="control" id="level"><option value="">全部级别</option><option value="INFO">INFO</option><option value="WARNING">WARNING</option><option value="ERROR">ERROR</option><option value="CRITICAL">CRITICAL</option></select><select class="control" id="module"><option value="">全部类型</option></select><select class="control" id="range"><option value="0">全部时间</option><option value="3600">最近1小时</option><option value="86400">最近24小时</option><option value="604800">最近7天</option></select><button class="btn" id="reset">重置</button></div><div class="panel"><div class="thead"><span>时间</span><span>级别</span><span>类型</span><span>日志内容</span></div><div id="list"><div class="state">正在加载日志…</div></div><div class="pager" id="pager"></div></div></section></main></div><div id="toast" class="toast"></div><script>
const S={page:1,page_size:50,keyword:'',level:'',module:'',range_seconds:'0'};const $=s=>document.querySelector(s),esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),dt=v=>v?new Date(Number(v)*1000).toLocaleString('zh-CN',{hour12:false}):'-';const MODULES={'resources':'影视资源 / 影巢','media':'影视资料 / Emby','115':'115 转存','notifications':'通知','subscriptions':'订阅任务','offline':'ED2K / 离线','telegram':'Telegram','channel':'频道监控','explore':'汇影发现'};function moduleLabel(m){return MODULES[m]||m||'-'}function row(x){return `<article class="row"><span class="time">${dt(x.ts)}</span><span class="lv ${esc(x.level)}">${esc(x.level)}</span><span class="mod" title="${esc(x.module||'')}">${esc(moduleLabel(x.module))}</span><span class="msg">${esc(x.message)}</span></article>`}async function load(){const q=new URLSearchParams();for(const[k,v]of Object.entries(S))if(v&&v!=='0')q.set(k,v);try{const r=await fetch('/api/web/logs?'+q),d=await r.json();if(!r.ok)throw Error(d.detail||'加载失败');if(!d.items.length)$('#list').innerHTML='<div class="state"><h2>没有匹配的日志</h2><p>可以放宽筛选条件。</p></div>';else{$('#list').innerHTML=d.items.map(row).join('')}$('#pager').innerHTML=`<button id="prev" ${d.page<=1?'disabled':''}>‹</button><span>第 ${d.page} / ${d.total_pages} 页 · 共 ${d.total} 条</span><button id="next" ${!d.has_more?'disabled':''}>›</button>`;$('#prev').onclick=()=>{S.page--;load()};$('#next').onclick=()=>{S.page++;load()}}catch(e){$('#list').innerHTML=`<div class="state"><h2>日志加载失败</h2><p>${esc(e.message)}</p></div>`}}async function modules(){try{const d=await fetch('/api/web/logs/modules').then(r=>r.json());const sel=$('#module');(d.modules||[]).forEach(m=>{const o=document.createElement('option');o.value=m;o.textContent=moduleLabel(m)+' · '+m;sel.appendChild(o)})}catch(e){}}let timer;$('#keyword').oninput=e=>{clearTimeout(timer);timer=setTimeout(()=>{S.keyword=e.target.value;S.page=1;load()},350)};for(const [id,key] of [['level','level'],['module','module'],['range','range_seconds']])$('#'+id).onchange=e=>{S[key]=e.target.value;S.page=1;load()};$('#reset').onclick=()=>{Object.assign(S,{page:1,keyword:'',level:'',module:'',range_seconds:'0'});['keyword','level','module','range'].forEach(id=>$('#'+id).value='');load()};$('#refresh').onclick=load;let autoTimer;$('#auto').onchange=e=>{if(e.target.checked)autoTimer=setInterval(()=>load(),8000);else clearInterval(autoTimer)};modules();load();
</script></body></html>'''
